// Dynamic Symbol Resolution via PLT/GOT

// Global Offset Table (GOT) entry structure
typedef struct {
    uint64_t addr; // Resolved function/data address
} GOT_Entry;

// PLT entry (Procedure Linkage Table)
// Resolves function call 'TargetFunc' dynamically
TargetFunc@plt:
    JMP *(GOT_Entry_TargetFunc) // 1. Try indirect jump
    PUSH $RelocIndex_TargetFunc // 2. If first call, push ID
    JMP .PLT_RESOLVER           // 3. Jump to Dynamic Linker

// Linker Rule: Strong vs. Weak Symbols
// int foo = 1;      // Default: Strong definition
// __attribute__((weak)) int bar = 2; // Weak definition

// Resolution Priority:
// Strong + Strong = Error
// Strong + Weak   = Strong
// Weak + Weak     = Arbitrary (often largest definition used)
